                .sorted(Comparator.comparing(Person::getName).thenComparing(Person::getId))
                .toList();
    }

    /** Replaces the people this person follows; whether they follow this person back is unchanged. */
    public void setAllies(Set<Person> allies) {
        this.follows = new HashSet<>(allies);
    }

    /** The derived values exist only once alpha, beta and gamma are all given. */
    private boolean complete() {
        return alpha != null && beta != null && gamma != null;
    }

    /** Thrust is alpha multiplied by beta; absent until alpha, beta and gamma are all given. */
    public Integer getThrust() {
        return complete() ? alpha * beta : null;
    }

    /** Drift is gamma minus alpha; absent until alpha, beta and gamma are all given. */
    public Integer getDrift() {
        return complete() ? gamma - alpha : null;
    }

    /** Momentum is thrust plus three times drift; absent while either is absent. */
    public Integer getMomentum() {
        Integer thrust = getThrust();
        Integer drift = getDrift();
        return thrust == null || drift == null ? null : thrust + 3 * drift;
    }

    /** Whether all of delta, epsilon and zeta are given; the concepts built on them are absent until they are. */
    private boolean hasSecondAxis() {
        return delta != null && epsilon != null && zeta != null;
    }

    /** Force is delta multiplied by epsilon; absent while any of delta, epsilon or zeta is absent. */
    public Integer getForce() {
        return hasSecondAxis() ? delta * epsilon : null;
    }

    /** Sway is zeta minus delta; absent while any of delta, epsilon or zeta is absent. */
    public Integer getSway() {
        return hasSecondAxis() ? zeta - delta : null;
    }

    /** Torque is force plus three times sway; absent while either is absent. */
    public Integer getTorque() {
        Integer force = getForce();
        Integer sway = getSway();
        return force == null || sway == null ? null : force + 3 * sway;
    }

    /** Pivot is torque times verge; absent while either is absent. */
    public Integer getPivot() {
        Integer torque = getTorque();
        Integer verge = getVerge();
        return torque == null || verge == null ? null : torque * verge;
    }

    /** Blend is momentum plus torque; absent while either is absent. */
    public Integer getBlend() {
        Integer momentum = getMomentum();
        Integer torque = getTorque();
        return momentum == null || torque == null ? null : momentum + torque;
    }

    /** Load is momentum times weight; absent while either is absent. */
    public Integer getLoad() {
