            case 'N' -> 2;
            case 'S' -> 3;
            default -> 1;
        };
    }

    /** Reach is the sum over the regions of momentum times the region's multiplier; absent without momentum or regions. */
    public Integer getReach() {
        Integer momentum = getMomentum();
        if (momentum == null || regions.isEmpty()) {
            return null;
        }
        return regions.stream().mapToInt(r -> momentum * regionMultiplier(r)).sum();
    }

    /** Backing is the sum of the patrons' thrust; absent without patrons or while any patron's thrust is absent. */
    public Integer getBacking() {
        if (patrons.isEmpty()) {
            return null;
        }
        int sum = 0;
        for (Person patron : patrons) {
            Integer thrust = patron.getThrust();
            if (thrust == null) {
                return null;
            }
            sum += thrust;
        }
        return sum;
    }

    /** Flux is the average of the patrons' force, rounded down; zero without patrons, absent while any patron's force is absent. */
    public Integer getFlux() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer force = patron.getForce();
            if (force == null) {
                return null;
            }
            sum += force;
        }
        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
    }

    /** Crest is blend plus flux; absent while either is absent. */
    public Integer getCrest() {
        Integer blend = getBlend();
        Integer flux = getFlux();
        return blend == null || flux == null ? null : blend + flux;
    }

    /** Swing is the sum of the positive torque of the people followed (zero or below is dropped); zero without allies, absent while any ally's torque is absent. */
    public Integer getSwing() {
        int sum = 0;
        for (Person ally : getAllies()) {
            Integer torque = ally.getTorque();
            if (torque == null) {
                return null;
            }
            if (torque > 0) {
                sum += torque;
            }
        }
        return sum;
    }

    /** Vector is the average of the patrons' blend, rounded down; zero without patrons, absent while any patron's blend is absent. */
    public Integer getVector() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer blend = patron.getBlend();
            if (blend == null) {
                return null;
            }
            sum += blend;
        }
        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
    }

    /** Haul is crest plus swing; absent while either is absent. */
    public Integer getHaul() {
        Integer crest = getCrest();
        Integer swing = getSwing();
        return crest == null || swing == null ? null : crest + swing;
    }

    /** Synergy is the sum of the thrust of the people followed; zero without allies, absent while any ally's thrust is absent. */
    public Integer getSynergy() {
        int sum = 0;
        for (Person ally : getAllies()) {
            Integer thrust = ally.getThrust();
            if (thrust == null) {
                return null;
            }
            sum += thrust;
        }
        return sum;
    }

    /** Net is momentum plus backing, counting backing as zero without patrons; absent with momentum, or with a patron whose thrust is absent. */
    public Integer getNet() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        if (patrons.isEmpty()) {
            return momentum;
        }
        Integer backing = getBacking();
        return backing == null ? null : momentum + backing;
    }

    /** Effective is net while active, and half of net rounded down while not active (absent while net is). */
    public Integer getEffective() {
        Integer net = getNet();
        if (net == null || active) {
            return net;
        }
        return Math.floorDiv(net, 2);
    }

    /** Clout is the average of the patrons' effective, rounded down; zero without patrons, absent while any patron's effective is absent. */
    public Integer getClout() {
        int sum = 0;
        for (Person patron : patrons) {
            Integer effective = patron.getEffective();
            if (effective == null) {
                return null;
            }
            sum += effective;
        }
        return patrons.isEmpty() ? 0 : Math.floorDiv(sum, patrons.size());
    }

    /** Influence is effective plus clout; absent while either is. */
    public Integer getInfluence() {
        Integer effective = getEffective();
        Integer clout = getClout();
        return effective == null || clout == null ? null : effective + clout;
    }

    /** Brace is influence plus two times force; absent while either is. */
    public Integer getBrace() {
        Integer influence = getInfluence();
        Integer force = getForce();
        return influence == null || force == null ? null : influence + 2 * force;
    }

    /**
     * Tide is the sum of the brace of the people followed, each taken as momentum plus two times force, counting only
     * positive braces; zero without allies, absent while any ally's momentum or force is absent.
     */
    public Integer getTide() {
        int sum = 0;
        for (Person ally : getAllies()) {
            Integer momentum = ally.getMomentum();
            Integer force = ally.getForce();
            if (momentum == null || force == null) {
                return null;
            }
            int brace = momentum + 2 * force;
            if (brace > 0) {
                sum += brace;
            }
        }
        return sum;
    }

    /** Strain is crest minus brace; absent while either is. */
    public Integer getStrain() {
        Integer crest = getCrest();
        Integer brace = getBrace();
        return crest == null || brace == null ? null : crest - brace;
    }

    /** Pulse classifies strain against a tolerance band: NEG below -10, FLAT within 10 of zero, POS above 10; absent with strain. */
    public String getPulse() {
        Integer strain = getStrain();
        if (strain == null) {
            return null;
        }
        return strain < -10 ? "NEG" : strain > 10 ? "POS" : "FLAT";
    }

    /** Combined is influence plus synergy; absent while either is. */
    public Integer getCombined() {
        Integer influence = getInfluence();
        Integer synergy = getSynergy();
        return influence == null || synergy == null ? null : influence + synergy;
    }

    /** Tier classifies momentum: SINK below zero, STEADY up to 199, SURGE from 200; absent with momentum. */
    public String getTier() {
        Integer momentum = getMomentum();
        if (momentum == null) {
            return null;
        }
        return momentum < 0 ? "SINK" : momentum <= 199 ? "STEADY" : "SURGE";
    }

    /** Phase classifies torque: EBB below zero, RUN up to 199, PEAK from 200; absent with torque. */
    public String getPhase() {
        Integer torque = getTorque();
        if (torque == null) {
            return null;
        }
        return torque < 0 ? "EBB" : torque <= 199 ? "RUN" : "PEAK";
    }

    /** Drag classifies blend: L0 below zero, L1 up to 49, L2 up to 149, L3 from 150; absent with blend. */
    public String getDrag() {
        Integer blend = getBlend();
        if (blend == null) {
            return null;
        }
        return blend < 0 ? "L0" : blend <= 49 ? "L1" : blend <= 149 ? "L2" : "L3";
    }

    /** Lift is blend times the drag's multiplier: L0 0, L1 1, L2 2, L3 3; absent with blend. */
    public Integer getLift() {
        Integer blend = getBlend();
        if (blend == null) {
            return null;
        }
        int multiplier = switch (getDrag()) {
            case "L3" -> 3;
            case "L2" -> 2;
            case "L1" -> 1;
            default -> 0;
        };
        return blend * multiplier;
    }

    /** Yield is pivot plus two times lift; absent while either is absent. */
    public Integer getYield() {
        Integer pivot = getPivot();
        Integer lift = getLift();
        return pivot == null || lift == null ? null : pivot + 2 * lift;
    }

    /** Band classifies adjusted: E below 0, D up to 99, C up to 249, B up to 499, A from 500; absent with adjusted. */
    public String getBand() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        return adjusted < 0 ? "E" : adjusted <= 99 ? "D" : adjusted <= 249 ? "C" : adjusted <= 499 ? "B" : "A";
    }

    /** Scaled is adjusted times the band's multiplier: A 4, B 3, C 2, D 1, E 0; absent with adjusted. */
    public Integer getScaled() {
        Integer adjusted = getAdjusted();
        if (adjusted == null) {
            return null;
        }
        int multiplier = switch (getBand()) {
            case "A" -> 4;
            case "B" -> 3;
            case "C" -> 2;
            case "D" -> 1;
            default -> 0;
        };
        return adjusted * multiplier;
    }

    /** Thrum is scaled plus two times torque; absent while either is absent. */
    public Integer getThrum() {
        Integer scaled = getScaled();
        Integer torque = getTorque();
        return scaled == null || torque == null ? null : scaled + 2 * torque;
    }

    /** Spool is thrum minus blend; absent while either is absent. */
    public Integer getSpool() {
        Integer thrum = getThrum();
        Integer blend = getBlend();
        return thrum == null || blend == null ? null : thrum - blend;
    }

    /** Gust is reach plus two times torque; absent while either is absent. */
    public Integer getGust() {
        Integer reach = getReach();
        Integer torque = getTorque();
        return reach == null || torque == null ? null : reach + 2 * torque;
    }

    /** Coil is gust minus momentum; absent while either is absent. */
    public Integer getCoil() {
        Integer gust = getGust();
        Integer momentum = getMomentum();
        return gust == null || momentum == null ? null : gust - momentum;
    }

    /** Grip is yield minus coil; absent while either is absent. */
    public Integer getGrip() {
        Integer yield = getYield();
        Integer coil = getCoil();
        return yield == null || coil == null ? null : yield - coil;
    }

    /** Charge is vector plus yield; absent while either is absent. */
    public Integer getCharge() {
        Integer vector = getVector();
        Integer yield = getYield();
        return vector == null || yield == null ? null : vector + yield;
    }

    /** Churn is tide minus vector; absent while either is absent. */
    public Integer getChurn() {
        Integer tide = getTide();
        Integer vector = getVector();
        return tide == null || vector == null ? null : tide - vector;
    }

    /** Flow is yield plus charge; absent while either is absent. */
    public Integer getFlow() {
        Integer yield = getYield();
        Integer charge = getCharge();
        return yield == null || charge == null ? null : yield + charge;
    }
}

package net.officefloor.hq.app.people;

import java.time.LocalDate;
import java.util.Collection;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class PersonService {

    private final PersonRepository people;

    private final SheetRepository sheets;

    private final UnnamedSheetRepository unnamedSheet;

    private final PersonGroupRepository groups;

    private final Audit audit;

    public PersonService(PersonRepository people, SheetRepository sheets, UnnamedSheetRepository unnamedSheet,
            PersonGroupRepository groups, Audit audit) {
        this.people = people;
        this.groups = groups;
        this.sheets = sheets;
        this.unnamedSheet = unnamedSheet;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    /** The people on a sheet; a null sheet id is the unnamed sheet. */
    public List<Person> list(String sheetId) {
        return people.findBySheetId(sheetId, Sort.by("localId"));
    }

    /** Whether a named sheet has been stored. */
    @Transactional(readOnly = true)
    public boolean sheetExists(String sheetId) {
        return sheets.existsById(sheetId);
    }

    /**
     * A sheet's anchor date: the one set on it, or today when none is set; a null sheet id is the
     * unnamed sheet.
     */
    @Transactional(readOnly = true)
    public LocalDate anchor(String sheetId) {
        Optional<LocalDate> anchor = sheetId == null
                ? unnamedSheet.findById(UnnamedSheet.ID).map(UnnamedSheet::getAnchor)
                : sheets.findById(sheetId).map(Sheet::getAnchor);
        return anchor.orElseGet(LocalDate::now);
    }

    /** Opens a named sheet, storing it as a new empty sheet when it does not exist yet. */
    @Transactional
    public Sheet openSheet(String sheetId) {
        return sheets.findById(sheetId).orElseGet(() -> sheets.save(new Sheet(sheetId)));
    }

    /** The person with an id on a sheet; a null sheet id is the unnamed sheet. */
    @Transactional(readOnly = true)
    public Optional<Person> find(String sheetId, long id) {
        return people.findBySheetIdAndLocalId(sheetId, id);
    }

    @Transactional
    /** Adds a person to a sheet (null for the unnamed sheet), creating the sheet on first use. */
    public Person add(String sheetId, String name, Integer alpha, Integer beta, Integer gamma, Integer delta, Integer epsilon, Integer zeta,
            Grade grade, Kind kind, Collection<String> regions, Long groupId) {
        ensureSheet(sheetId);
        PersonGroup group = group(sheetId, groupId);
        long id = people.maxLocalId(sheetId) + 1;
        Person person = new Person(sheetId, id, name.trim(), alpha, beta, gamma);
        person.setDelta(delta);
        person.setEpsilon(epsilon);
        person.setZeta(zeta);
        person.setGrade(grade);
        person.setKind(kind);
        person.setRegions(regions);
        person.setGroup(group);
        return people.save(person);
    }

    /** The groups on a sheet, by id; a null sheet id is the unnamed sheet. */
    @Transactional(readOnly = true)
    public List<PersonGroup> groups(String sheetId) {
        return groups.findBySheetId(sheetId, Sort.by("localId"));
    }

    /** Adds a named group to a sheet (null for the unnamed sheet), creating the sheet on first use. */
    @Transactional
    public PersonGroup addGroup(String sheetId, String name) {
        ensureSheet(sheetId);
        return groups.save(new PersonGroup(sheetId, groups.maxLocalId(sheetId) + 1, name.trim()));
    }

    /** Puts the person in the group with an id on the same sheet; null takes them out of any group. Refuses an unknown group. */
    @Transactional
    public Optional<Person> setGroup(String sheetId, long id, Long groupId) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setGroup(group(sheetId, groupId));
            return p;
        });
    }

    private PersonGroup group(String sheetId, Long groupId) {
        if (groupId == null) {
            return null;
        }
        return groups.findBySheetIdAndLocalId(sheetId, groupId)
                .orElseThrow(() -> new IllegalArgumentException("no group " + groupId + " on this sheet"));
    }

    private void ensureSheet(String sheetId) {
        if (sheetId != null && !sheets.existsById(sheetId)) {
            sheets.save(new Sheet(sheetId));
        }
    }

    @Transactional
    /** Sets alpha; a real change is recorded in the audit as ALPHA_CHANGED id=.. from=.. to=... */
    public Optional<Person> setAlpha(String sheetId, long id, Integer alpha) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            Integer previous = p.getAlpha();
            p.setAlpha(alpha);
            if (!Objects.equals(previous, alpha)) {
                audit.record("ALPHA_CHANGED id=" + id + " from=" + previous + " to=" + alpha);
            }
            return p;
        });
    }

    @Transactional
    public Optional<Person> setBeta(String sheetId, long id, Integer beta) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setBeta(beta);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setGamma(String sheetId, long id, Integer gamma) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setGamma(gamma);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setDelta(String sheetId, long id, Integer delta) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setDelta(delta);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setEpsilon(String sheetId, long id, Integer epsilon) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setEpsilon(epsilon);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setZeta(String sheetId, long id, Integer zeta) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setZeta(zeta);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setGrade(String sheetId, long id, Grade grade) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setGrade(grade);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setKind(String sheetId, long id, Kind kind) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setKind(kind);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setRegions(String sheetId, long id, Collection<String> regions) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setRegions(regions);
            return p;
        });
    }

    @Transactional
    public Optional<Person> setActive(String sheetId, long id, boolean active) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setActive(active);
            return p;
        });
    }

    /** Moves the person forward to their next state (REWORK back to FINAL), recorded in the audit as STATE_CHANGED id=.. from=.. to=...; refused once FINAL. */
    @Transactional
    public Optional<Person> advance(String sheetId, long id) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            State previous = p.getState();
            State next = previous.next();
            if (next == null) {
                throw new IllegalStateException("a person at " + previous + " cannot move forward");
            }
            p.setState(next);
            audit.record("STATE_CHANGED id=" + id + " from=" + previous + " to=" + next);
            return p;
        });
    }

    /** Reopens a FINAL person to REWORK, recorded in the audit like {@link #advance}; refused unless FINAL. */
    @Transactional
    public Optional<Person> rework(String sheetId, long id) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            State current = p.getState();
            State reopened = current.reopened();
            if (reopened == null) {
                throw new IllegalStateException("a person at " + current + " cannot be reworked");
            }
            p.setState(reopened);
            audit.record("STATE_CHANGED id=" + id + " from=" + current + " to=" + reopened);
            return p;
        });
    }

    /** Moves the person back to their previous state, recorded in the audit like {@link #advance}; refused once FINAL, at REWORK or at DRAFT. */
    @Transactional
    public Optional<Person> demote(String sheetId, long id) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            State current = p.getState();
            State previous = current.previous();
            if (previous == null) {
                throw new IllegalStateException("a person at " + current + " cannot move back");
            }
            p.setState(previous);
            audit.record("STATE_CHANGED id=" + id + " from=" + current + " to=" + previous);
            return p;
        });
    }

    /** Sets the person's whole-number score; null clears it. */
    @Transactional
    public Optional<Person> setScore(String sheetId, long id, Integer score) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            p.setScore(score);
            return p;
        });
    }

    /** Sets the patrons (other people on the same sheet) by their id on that sheet; an empty list clears them. Refuses oneself or an unknown person. */
    @Transactional
    public Optional<Person> setPatrons(String sheetId, long id, Collection<Long> patronIds) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            Set<Person> patrons = new HashSet<>();
            for (Long patronId : patronIds) {
                if (patronId == id) {
                    throw new IllegalArgumentException("a person cannot be their own patron");
                }
                patrons.add(people.findBySheetIdAndLocalId(sheetId, patronId)
                        .orElseThrow(() -> new IllegalArgumentException("no person " + patronId + " on this sheet")));
            }
            p.setPatrons(patrons);
            return p;
        });
    }

    /** Sets the allies (the other people on the same sheet this person follows) by their id on that sheet; an empty list clears them. Following is one-directional. Refuses oneself or an unknown person. */
    @Transactional
    public Optional<Person> setAllies(String sheetId, long id, Collection<Long> allyIds) {
        return people.findBySheetIdAndLocalId(sheetId, id).map(p -> {
            Set<Person> allies = new HashSet<>();
            for (Long allyId : allyIds) {
                if (allyId == id) {
                    throw new IllegalArgumentException("a person cannot be their own ally");
                }
                allies.add(people.findBySheetIdAndLocalId(sheetId, allyId)
                        .orElseThrow(() -> new IllegalArgumentException("no person " + allyId + " on this sheet")));
            }
            p.setAllies(allies);
            return p;
        });
    }
}
package net.officefloor.hq.app.people;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.Function;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma, Integer delta, Integer epsilon, Integer zeta,
            Grade grade, Integer weight, Kind kind, Integer verge, Integer thrust, Integer drift, Integer momentum, Integer force, Integer sway, Integer torque, Integer pivot, Integer blend, Integer flux, Integer crest, Integer swing, Integer haul, Integer vector, String phase, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective,
            Integer clout, Integer influence, Integer brace, Integer tide, Integer strain, String pulse, List<String> regions, Integer reach, Integer gust, Integer coil,
            List<PatronView> allies, int allyCount, Integer synergy, Integer combined, Integer score, int noteSum, Integer quality, Integer adjusted, String band, Integer scaled, Integer thrum, Integer spool, String drag, Integer lift, Integer yield, Integer grip, Integer charge, Integer churn, Integer flow, Integer norm, boolean outlier, State state, Integer ebb, boolean stray,
            Long groupId, String groupName) {
        static PersonView of(Person p, Map<Long, Integer> ranks, Integer medianScaled, Integer meanBlend, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(), p.getDelta(), p.getEpsilon(), p.getZeta(),
                    p.getGrade(), p.getWeight(), p.getKind(), p.getVerge(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getForce(), p.getSway(), p.getTorque(), p.getPivot(), p.getBlend(), p.getFlux(), p.getCrest(), p.getSwing(), p.getHaul(), p.getVector(), p.getPhase(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective(), p.getClout(),
                    p.getInfluence(), p.getBrace(), p.getTide(), p.getStrain(), p.getPulse(), p.getRegions(), p.getReach(), p.getGust(), p.getCoil(),
                    p.getAllies().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getAllies().size(), p.getSynergy(), p.getCombined(), p.getScore(), p.getNoteSum(), p.getQuality(), p.getAdjusted(), p.getBand(), p.getScaled(), p.getThrum(), p.getSpool(), p.getDrag(), p.getLift(), p.getYield(), p.getGrip(), p.getCharge(), p.getChurn(), p.getFlow(),
                    PersonController.norm(p.getScaled(), medianScaled),
                    PersonController.outlier(PersonController.norm(p.getScaled(), medianScaled)), p.getState(),
                    PersonController.ebb(p.getBlend(), meanBlend),
                    PersonController.stray(PersonController.ebb(p.getBlend(), meanBlend)),
                    p.getGroup() == null ? null : p.getGroup().getLocalId(),
                    p.getGroup() == null ? null : p.getGroup().getName());
        }
    }

    /**
     * A rank as a percentile of the ranked people: the best 100, the worst 0, evenly spread between
     * by rank and rounded to a whole number. A lone ranked person is 100; unranked has none.
     */
    static Integer percentile(Integer rank, int ranked) {
        if (rank == null) {
            return null;
        }
        if (ranked <= 1) {
            return 100;
        }
        return (int) Math.round((ranked - rank) * 100.0 / (ranked - 1));
    }

    /** Norm is scaled minus the sheet's median scaled; absent while either is absent. */
    static Integer norm(Integer scaled, Integer medianScaled) {
        return scaled == null || medianScaled == null ? null : scaled - medianScaled;
    }

    /** Ebb is blend minus the sheet's mean blend (rounded down); absent while either is absent. */
    static Integer ebb(Integer blend, Integer meanBlend) {
        return blend == null || meanBlend == null ? null : blend - meanBlend;
    }

    /** A stray has an ebb more than 100 away from zero in either direction; without an ebb, not a stray. */
    static boolean stray(Integer ebb) {
        return ebb != null && Math.abs(ebb) > 100;
    }

    /** An outlier has a norm more than 100 away from zero in either direction; without a norm, not an outlier. */
    static boolean outlier(Integer norm) {
        return norm != null && Math.abs(norm) > 100;
    }

    /**
     * The median scaled of the people whose scaled can be worked out; for an even count, the lower of
     * the two middle values. Absent when there are none.
     */
    private static Integer medianScaled(List<Person> people) {
        return median(people, Person::getScaled);
    }

    /**
     * The mean blend of the people whose blend can be worked out, rounded down. Absent when there are
     * none.
     */
    private static Integer meanBlend(List<Person> people) {
        List<Integer> values = people.stream().map(Person::getBlend).filter(v -> v != null).toList();
        if (values.isEmpty()) {
            return null;
        }
        long sum = values.stream().mapToLong(Integer::longValue).sum();
        return (int) Math.floorDiv(sum, (long) values.size());
    }

    /** The median of a value over the people who have it, the lower middle for an even count; absent when none do. */
    private static Integer median(List<Person> people, Function<Person, Integer> value) {
        List<Integer> values = people.stream().map(value).filter(v -> v != null).sorted().toList();
        if (values.isEmpty()) {
            return null;
        }
        return values.get((values.size() - 1) / 2);
    }

    /** Highest momentum first; equal momentum by higher alpha, then by name, earlier in the alphabet first. */
    private static final Comparator<Person> RANK_ORDER = Comparator
            .comparing(Person::getMomentum, Comparator.reverseOrder())
            .thenComparing(Person::getAlpha, Comparator.nullsLast(Comparator.reverseOrder()))
            .thenComparing(Person::getName)
            .thenComparing(Person::getLocalId);

    public record PatronView(Long id, String name) {
    }

    public record NewPerson(@NotBlank String name, Integer alpha, Integer beta, Integer gamma, Integer delta, Integer epsilon, Integer zeta, Grade grade, Kind kind, List<String> regions, Long groupId) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(@RequestParam(required = false) String sheet) {
        String sheetId = sheetId(sheet);
        List<Person> people = service.list(sheetId);
        Map<Long, Integer> ranks = ranks(people);
        Integer medianScaled = medianScaled(people);
        Integer meanBlend = meanBlend(people);
        LocalDate anchor = service.anchor(sheetId);
        return people.stream().map(p -> PersonView.of(p, ranks, medianScaled, meanBlend, anchor)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@RequestParam(required = false) String sheet, @Valid @RequestBody NewPerson person) {
        try {
            return view(sheetId(sheet), service.add(sheetId(sheet), person.name(), person.alpha(), person.beta(), person.gamma(),
                    person.delta(), person.epsilon(), person.zeta(), person.grade(), person.kind(), regions(person.regions()),
                    person.groupId()));
        } catch (IllegalArgumentException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
        }
    }

    /** Moves the person with this id on the request's sheet forward to their next state (REWORK back to FINAL); refused once FINAL. */
    @PostMapping("/{id}/advance")
    public PersonView advance(@RequestParam(required = false) String sheet, @PathVariable long id) {
        String sheetId = sheetId(sheet);
        try {
            return service.advance(sheetId, id).map(p -> view(sheetId, p))
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
        } catch (IllegalStateException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, e.getMessage());
        }
    }

    /** Reopens the FINAL person with this id on the request's sheet to REWORK; refused unless FINAL. */
    @PostMapping("/{id}/rework")
    public PersonView rework(@RequestParam(required = false) String sheet, @PathVariable long id) {
        String sheetId = sheetId(sheet);
        try {
            return service.rework(sheetId, id).map(p -> view(sheetId, p))
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
        } catch (IllegalStateException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, e.getMessage());
        }
    }

    /** Moves the person with this id on the request's sheet back to their previous state; refused once FINAL, at REWORK or at DRAFT. */
    @PostMapping("/{id}/demote")
    public PersonView demote(@RequestParam(required = false) String sheet, @PathVariable long id) {
        String sheetId = sheetId(sheet);
        try {
            return service.demote(sheetId, id).map(p -> view(sheetId, p))
                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
        } catch (IllegalStateException e) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, e.getMessage());
        }
    }

    /**
     * Sets, on the person with this id on the request's sheet, whichever of alpha, beta, gamma, delta, epsilon, zeta, score, grade, kind, regions (a list of codes), active
     * (true or false), patronIds and allyIds (lists of ids on that sheet) and groupId (a group's id on that sheet) the body names; a null value clears it.
     */
    @PatchMapping("/{id}")
    public PersonView update(@RequestParam(required = false) String sheet, @PathVariable long id,
            @RequestBody Map<String, Object> update) {
        String sheetId = sheetId(sheet);
        Optional<Person> person = service.find(sheetId, id);
        if (update.containsKey("alpha")) {
            person = service.setAlpha(sheetId, id, integer(update.get("alpha")));
        }
        if (update.containsKey("beta")) {
            person = service.setBeta(sheetId, id, integer(update.get("beta")));
        }
        if (update.containsKey("gamma")) {
            person = service.setGamma(sheetId, id, integer(update.get("gamma")));
        }
        if (update.containsKey("delta")) {
            person = service.setDelta(sheetId, id, integer(update.get("delta")));
        }
        if (update.containsKey("epsilon")) {
            person = service.setEpsilon(sheetId, id, integer(update.get("epsilon")));
        }
        if (update.containsKey("zeta")) {
            person = service.setZeta(sheetId, id, integer(update.get("zeta")));
        }
        if (update.containsKey("score")) {
            person = service.setScore(sheetId, id, integer(update.get("score")));
        }
        if (update.containsKey("grade")) {
            person = service.setGrade(sheetId, id, grade(update.get("grade")));
        }
        if (update.containsKey("kind")) {
            person = service.setKind(sheetId, id, kind(update.get("kind")));
        }
        if (update.containsKey("regions")) {
            List<String> regions = new ArrayList<>();
            if (update.get("regions") instanceof List<?> values) {
                for (Object region : values) {
                    if (!(region instanceof String text)) {
                        throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "regions must be text");
                    }
                    regions.add(text);
                }
            } else if (update.get("regions") != null) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "regions must be a list");
            }
            person = service.setRegions(sheetId, id, regions(regions));
        }
        if (update.containsKey("active")) {
            if (!(update.get("active") instanceof Boolean active)) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "active must be true or false");
            }
            person = service.setActive(sheetId, id, active);
        }
        if (update.containsKey("patronIds")) {
            List<Long> patronIds = new ArrayList<>();
            if (update.get("patronIds") instanceof List<?> ids) {
                for (Object patronId : ids) {
                    patronIds.add(integer(patronId).longValue());
                }
            } else if (update.get("patronIds") != null) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "patronIds must be a list");
            }
            try {
                person = service.setPatrons(sheetId, id, patronIds);
            } catch (IllegalArgumentException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
            }
        }
        if (update.containsKey("allyIds")) {
            List<Long> allyIds = new ArrayList<>();
            if (update.get("allyIds") instanceof List<?> ids) {
                for (Object allyId : ids) {
                    allyIds.add(integer(allyId).longValue());
                }
            } else if (update.get("allyIds") != null) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "allyIds must be a list");
            }
            try {
                person = service.setAllies(sheetId, id, allyIds);
            } catch (IllegalArgumentException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
            }
        }
        if (update.containsKey("groupId")) {
            Integer groupId = integer(update.get("groupId"));
            try {
                person = service.setGroup(sheetId, id, groupId == null ? null : groupId.longValue());
            } catch (IllegalArgumentException e) {
                throw new ResponseStatusException(HttpStatus.BAD_REQUEST, e.getMessage());
            }
        }
        return person.map(p -> view(sheetId, p))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND));
    }

    /** A person's view, ranked among the people on their sheet. */
    private PersonView view(String sheetId, Person person) {
        List<Person> people = service.list(sheetId);
        return PersonView.of(person, ranks(people), medianScaled(people), meanBlend(people), service.anchor(sheetId));
    }

    /**
     * Each person's rank by local id: 1 for the highest momentum, then 2, 3, ... with equal momentum
     * ordered by higher alpha, then by name. People without a momentum are not ranked.
     */
    private static Map<Long, Integer> ranks(List<Person> people) {
        List<Person> ranked = people.stream().filter(p -> p.getMomentum() != null).sorted(RANK_ORDER).toList();
        Map<Long, Integer> ranks = new HashMap<>();
        for (int i = 0; i < ranked.size(); i++) {
            ranks.put(ranked.get(i).getLocalId(), i + 1);
        }
        return ranks;
    }

